type BatchOperation =
  | { collection: string; data: Json; type: "add" }
  | ({ collection: string; id: string } & Conditional &
      (
        | { data: Json; type: "set" }
        | { data: Json; type: "update"; unset?: string[] }
        | { type: "delete" }
      ))

type BatchResult<T extends BatchOperation = BatchOperation> = T extends {
  type: "delete";
}
  ? { success: true }
  : Written

type BatchResults<T extends readonly BatchOperation[]> = {
  -readonly [K in keyof T]: BatchResult<T[K]>;
}

